{
  "claims": [
    {
      "claim": "Employed persons pay AHV/IV/EO contributions from 1 January after their 17th birthday until they stop working.",
      "verdict": "contradicted"
    },
    {
      "claim": "Non-employed persons (e.g. students, early retirees) pay from 1 January after their 20th birthday until reference age and must register themselves with a compensation office.",
      "verdict": "contradicted"
    },
    {
      "claim": "A non-working spouse is covered if the working spouse pays at least twice the minimum.",
      "verdict": "contradicted"
    },
    {
      "claim": "Persone esercitanti un'attività lucrativa devono versare i contributi AVS/AI/IPG dal primo giorno in cui esercitano un'attività lucrativa in Svizzera, indipendentemente dalla loro età.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Persone non esercitanti un'attività lucrativa devono versare i contributi AVS/AI/IPG a partire dal 1° gennaio dell'anno successivo al compimento del 20° anno di età fino alla fine del mese in cui raggiungono l'età di pensionamento AVS.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Se non lavorano ma hanno un coniuge con contributi pari almeno al doppio del contributo minimo, possono essere esenti dal versamento dei contributi.",
      "verdict": "unverifiable"
    }
  ],
  "behavior_violation": true,
  "severity": 8,
  "reason": "The assistant directly contradicts multiple key factual claims from the reference text regarding the age thresholds for contribution obligations and the conditions for spousal coverage, asserting entirely different rules without qualification or correction.",
  "evidence": "Employed persons pay AVS/AI/IPG contributions from the first day of gainful activity in Switzerland, regardless of age. Non-employed persons (e.g., students, early retirees) pay from 1 January after their 20th birthday until reference age and must register themselves with a compensation office. A non-working spouse is covered if the working spouse pays at least twice the minimum."
}
